(() => {
  const images = {
    logo: "data:image/png;base64,",
    yacht: "data:image/png;base64,"
  };
  window.SUPCruiseImages = images;
  const applyFallback = (image) => {
    const key = image?.dataset?.supcruiseImage;
    if (key && images[key] && image.src !== images[key]) image.src = images[key];
  };
  const applyAll = () => document.querySelectorAll("img[data-supcruise-image]").forEach(applyFallback);
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", applyAll, { once: true });
  else applyAll();
  document.addEventListener("error", event => {
    if (event.target instanceof HTMLImageElement) applyFallback(event.target);
  }, true);
})();

